exercises.solution:
function conferirOvos(quantidade) {
  if (!Number.isInteger(quantidade)) {
    console.log(`${quantidade} ovos: não vendemos ovo partido`);
  } else {
    console.log(`${quantidade} ovos: pedido aceito`);
  }
}

conferirOvos(12);
conferirOvos(2.5);
conferirOvos(30);

