exercises.solution:
function lerSeries(texto) {
  const series = Number(texto.trim());
  if (Number.isInteger(series) && series >= 1 && series <= 5) {
    return series;
  } else {
    return null;
  }
}

console.log(lerSeries('3'));
console.log(lerSeries(' 5 '));
console.log(lerSeries('2.5'));
console.log(lerSeries('6'));
console.log(lerSeries('três'));
console.log(lerSeries(''));
